        answer: "オーバーグリップは、ラケットの元グリップの上に巻く薄いテープです。少しクッション性とグリップ感が増し、汗を吸い、グリップがわずかに太くなります。ウェットタイプはしっとり手に吸いつく感触で、ドライタイプは手汗の多い人に向いています。光ってきたり、すり減ったり、滑るようになったりしたら交換しましょう。よくプレーする人なら1週間から2週間ごとになることもあります。",
