        answer: "シコラーに勝つには、長いラリーを受け入れ、早くポイントを終わらせようとしないことです。余裕をもって深く打ち、短いボールが来たら前に入ってネットで決めましょう。相手の柔らかく高いボールは簡単にボレーできます。シコラーはたいてい後ろにいるのが好きなので、ドロップショットも効果的です。シコラーに負けるときはたいてい自分がミスをしているので、自分のミスを数え、リスクの高いショットをやめましょう。",
