        answer: "ハードヒッターには、たくさん打たせて、打ちやすいボールを与えないことです。1歩後ろに下がり、短くコンパクトなスイングで相手のスピードを利用して返し、センターに深く送って角度をつけさせないようにしましょう。強打する選手の多くは腰の高さのボールを好むので、低いスライスも高く深いボールも相手のリズムを崩します。ボールを返し続ければ、相手のミスが出てきます。",
