        answer: "いいえ、遅すぎることはありません。大人になってからテニスを始め、何十年も続けている人はたくさんいます。大人は説明を理解して目的をもって練習できるので、覚えるのが早いことがよくあります。早いうちに正しい技術を身につけましょう。体を守り、テニスを楽にしてくれます。プレー前にはウォームアップをし、自分の体力に合ったペースで進めてください。覚えている間に仲間と楽しむなら、ダブルスがおすすめです。",
        next: ["上達するまでどのくらいかかる？", "初心者はまず何を覚えればいい？", "初心者も教えていますか？"],
