        answer: "UTRはユニバーサル・テニス・レーティング（Universal Tennis Rating）の略で、年齢や性別に関係なくすべての選手に使われる、1から16.5までのひとつの尺度です。スコアや相手のレーティングを含む最近の試合結果から計算されるので、強い相手に接戦で負けても評価が上がることがあります。ジュニアや大学のテニス、実力の近い相手探しに広く使われています。取得するには、大会などで記録された試合結果が必要です。",
