        answer: "NTRPはおもにアメリカのUSTAの大人向けリーグで使われ、1.5から7.0までの短い尺度です。UTRは試合結果から算出される1から16.5までの長い尺度で、ジュニアや大学のテニス、多くの大会で人気があります。どちらが大切かはプレーする場所によって違い、リーグでプレーする人はたいていNTRP、ジュニアはUTRを気にすることが多いです。2つの間に正確な換算方法はありません。",
