        answer: "上手な人と打つのは効果があります。速いボールや強い回転に対応する中で、何が通用するかがすぐにわかるからです。ただし、新しいことを試したりポイントを取ったりできる、同じくらいのレベルの人ともプレーしましょう。上手な人に一緒に打ってもらうには、頼れる相手になることです。ボールを返し続け、しっかりウォームアップの相手をし、相手のやりたい練習に付き合いましょう。ヒッティングセッションも、高いレベルでラリーをする方法のひとつです。",
